INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_ART_ARTHUR_GEOFFR','ENT_ART_ARTHUR','SRC_GEOFFREY_MONMOUTH','Geoffrey of Monmouth, Historia Regum Britanniae','Geoffrey of Monmouth, Historia Regum Britanniae','XX.--_Arthur prepares for a war, and refuses to pay tribute to the Romans._ King Arthur, seeing all unanimously ready for his service, ordered them to return back to their countries with speed, and get ready the forces which they had promised, and to hasten to the general rendezvous upon the kalends of August, at the mouth of the river Barba, that from thence they might advance with them to the borders of the Allobroges, to meet the Romans.','J. A. Giles',1848,'https://www.gutenberg.org/ebooks/37848',NULL,'primary-verbatim',NULL,true,'English translation (J. A. Giles, in Old English Chronicles, Gutenberg #37848) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_AVALON_GEOFFR','ENT_ART_AVALON','SRC_GEOFFREY_MONMOUTH','Geoffrey of Monmouth, Historia Regum Britanniae','Geoffrey of Monmouth, Historia Regum Britanniae','Near the Sabrina and below the Thamesis lived the Hedui, whose principal cities were Ischalis and Avalonia. The baths, which were also called Aquae Solis, were made the seat of a colony, and became the perpetual residence of the Romans who possessed this part of Britain. This was a celebrated city, situated upon the river Abona, remarkable for its hot springs, which were formed into baths at a great expense.','J. A. Giles',1848,'https://www.gutenberg.org/ebooks/37848',NULL,'primary-verbatim',NULL,true,'English translation (J. A. Giles, in Old English Chronicles, Gutenberg #37848) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_BEDIVERE_GEOFFR','ENT_ART_BEDIVERE','SRC_GEOFFREY_MONMOUTH','Geoffrey of Monmouth, Historia Regum Britanniae','Geoffrey of Monmouth, Historia Regum Britanniae','Fly, dear sir, fly, for fear he may come, as he usually does, to lie with me, and finding you here most barbarously butcher you." Bedver, moved at what she said, as much as it is possible for human nature to be, endeavoured with kind words to assuage her grief, and to comfort her with the promise of speedy help: and then returned back to Arthur, and gave him an account of what he had met with.','J. A. Giles',1848,'https://www.gutenberg.org/ebooks/37848',NULL,'primary-verbatim',NULL,true,'English translation (J. A. Giles, in Old English Chronicles, Gutenberg #37848) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_GAWAIN_GEOFFR','ENT_ART_GAWAIN','SRC_GEOFFREY_MONMOUTH','Geoffrey of Monmouth, Historia Regum Britanniae','Geoffrey of Monmouth, Historia Regum Britanniae','Walgan, the son of Lot, was then a youth twelve years old, and was recommended by his uncle to the service of pope Supplicius, from whom he received arms. But to return to the history: as soon as Arthur arrived on the coast of Norway, king Riculf, attended with the whole power of that kingdom, met him, and gave him battle, in which, after a great loss of blood on both sides, the Britons at length had the advantage, and making a vigorous charge, killed Ricu','J. A. Giles',1848,'https://www.gutenberg.org/ebooks/37848',NULL,'primary-verbatim',NULL,true,'English translation (J. A. Giles, in Old English Chronicles, Gutenberg #37848) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_IGRAINE_GEOFFR','ENT_ART_IGRAINE','SRC_GEOFFREY_MONMOUTH','Geoffrey of Monmouth, Historia Regum Britanniae','Geoffrey of Monmouth, Historia Regum Britanniae','When he had a full relation made to him how matters had succeeded, he was sorry for the death of Gorlois, but rejoiced that Igerna was now at liberty to marry again. Then he returned to the town of Tintagel, which he took, and in it, what he impatiently wished for, Igerna herself. After this they continued to live together with much affection for each other, and had a son and daughter, whose names were Arthur and Anne. CHAP.','J. A. Giles',1848,'https://www.gutenberg.org/ebooks/37848',NULL,'primary-verbatim',NULL,true,'English translation (J. A. Giles, in Old English Chronicles, Gutenberg #37848) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_KAY_GEOFFR','ENT_ART_KAY','SRC_GEOFFREY_MONMOUTH','Geoffrey of Monmouth, Historia Regum Britanniae','Geoffrey of Monmouth, Historia Regum Britanniae','The next night, therefore, at the second hour, Arthur, taking along with him Caius the sewer, and Bedver the butler, went out privately from the camp, and hastened towards the mountain. For being a man of undaunted courage, he did not care to lead his army against such monsters; both because he could in this manner animate his men by his own example, and also because he was alone sufficient to deal with them.','J. A. Giles',1848,'https://www.gutenberg.org/ebooks/37848',NULL,'primary-verbatim',NULL,true,'English translation (J. A. Giles, in Old English Chronicles, Gutenberg #37848) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_MERLIN_GEOFFR','ENT_ART_MERLIN','SRC_GEOFFREY_MONMOUTH','Geoffrey of Monmouth, Historia Regum Britanniae','Geoffrey of Monmouth, Historia Regum Britanniae','Legions, went to the king, and said, "If any one living is able to execute your commands, Merlin, the prophet of Vortigern, is the man. In my opinion there is not in all your kingdom a person of a brighter genius, either in predicting future events, or in mechanical contrivances.','J. A. Giles',1848,'https://www.gutenberg.org/ebooks/37848',NULL,'primary-verbatim',NULL,true,'English translation (J. A. Giles, in Old English Chronicles, Gutenberg #37848) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ART_UTHER_PENDRAGON_GEOFFR','ENT_ART_UTHER_PENDRAGON','SRC_GEOFFREY_MONMOUTH','Geoffrey of Monmouth, Historia Regum Britanniae','Geoffrey of Monmouth, Historia Regum Britanniae','XVII.--_Uther Pendragon is made king of Britain._ But Uther his brother, having assembled the clergy of the kingdom, took the crown, and by universal consent was advanced to the kingdom. And remembering the explanation which Merlin had made of the star above-mentioned, he commanded two dragons to be made of gold, in likeness of the dragon which he had seen at the ray of the star.','J. A. Giles',1848,'https://www.gutenberg.org/ebooks/37848',NULL,'primary-verbatim',NULL,true,'English translation (J. A. Giles, in Old English Chronicles, Gutenberg #37848) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
